import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DoubleMetaphone_isDoubleMetaphoneEqual_TriageGen1Test {

    private DoubleMetaphone doubleMetaphone;

    @Before
    public void setUp() {
        doubleMetaphone = new DoubleMetaphone();
    }

    @Test
    public void testIsDoubleMetaphoneEqual_WithAlternateFalse_True() {
        // Testing phonetic equality for common names
        // "Smith" and "Schmidt" often result in the same Metaphone code
        assertTrue(doubleMetaphone.isDoubleMetaphoneEqual("Smith", "Schmidt", false));
    }
















}

